#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    ll *data;
    int size;
    int capacity;
} Heap;

void heap_init(Heap *h, int cap, int is_max) {
    h->data = (ll*)malloc((cap+1) * sizeof(ll));
    h->size = 0;
    h->capacity = cap;
    // We store is_max as sign in data[0] for simplicity; we'll handle compare differently
    h->data[0] = is_max ? LLONG_MAX : LLONG_MIN;
}

void swap(ll *a, ll *b) {
    ll t = *a;
    *a = *b;
    *b = t;
}

void push_max(Heap *h, ll val) {
    int i = ++(h->size);
    while (i > 1 && val > h->data[i/2]) {
        h->data[i] = h->data[i/2];
        i /= 2;
    }
    h->data[i] = val;
}

ll pop_max(Heap *h) {
    ll maxv = h->data[1];
    ll last = h->data[(h->size)--];
    int i = 1, child;
    while (i*2 <= h->size) {
        child = i*2;
        if (child+1 <= h->size && h->data[child+1] > h->data[child])
            child++;
        if (last >= h->data[child]) break;
        h->data[i] = h->data[child];
        i = child;
    }
    h->data[i] = last;
    return maxv;
}

void push_min(Heap *h, ll val) {
    int i = ++(h->size);
    while (i > 1 && val < h->data[i/2]) {
        h->data[i] = h->data[i/2];
        i /= 2;
    }
    h->data[i] = val;
}

ll pop_min(Heap *h) {
    ll minv = h->data[1];
    ll last = h->data[(h->size)--];
    int i = 1, child;
    while (i*2 <= h->size) {
        child = i*2;
        if (child+1 <= h->size && h->data[child+1] < h->data[child])
            child++;
        if (last <= h->data[child]) break;
        h->data[i] = h->data[child];
        i = child;
    }
    h->data[i] = last;
    return minv;
}

ll peek(Heap *h) {
    return h->data[1];
}

