// Min-heap for left (to keep N largest)
// Max-heap for right (to keep N smallest)

long long heap[300005];
int heap_size;

// Min-heap operations
void push_min(long long val) {
    int i = ++heap_size;
    heap[i] = val;
    while (i > 1 && heap[i] < heap[i/2]) {
        long long tmp = heap[i]; heap[i] = heap[i/2]; heap[i/2] = tmp;
        i /= 2;
    }
}

long long top_min() { return heap[1]; }

void pop_min() {
    heap[1] = heap[heap_size--];
    int i = 1;
    while (1) {
        int s = i, l = 2*i, r = 2*i+1;
        if (l <= heap_size && heap[l] < heap[s]) s = l;
        if (r <= heap_size && heap[r] < heap[s]) s = r;
        if (s == i) break;
        long long tmp = heap[i]; heap[i] = heap[s]; heap[s] = tmp;
        i = s;
    }
}

// Max-heap: negate values
void push_max(long long val) { push_min(-val); }
long long top_max() { return -top_min(); }
void pop_max() { pop_min(); }

int main() {
    int N;
    scanf("%d", &N);
    int len = 3*N;
    long long *a = malloc(len * sizeof(long long));
    for (int i = 0; i < len; i++) scanf("%lld", &a[i]);

    long long *left = malloc((len+1) * sizeof(long long));
    long long *right = malloc((len+1) * sizeof(long long));

    // Compute left[i]: max sum of N elements from a[0..i-1]
    heap_size = 0;
    long long sum = 0;
    for (int i = 0; i < N; i++) { push_min(a[i]); sum += a[i]; }
    left[N] = sum;
    for (int i = N; i < 2*N; i++) {
        if (a[i] > top_min()) { sum += a[i] - top_min(); pop_min(); push_min(a[i]); }
        left[i+1] = sum;
    }

    // Compute right[i]: min sum of N elements from a[i..len-1]
    heap_size = 0;
    sum = 0;
    for (int i = len-1; i >= len-N; i--) { push_max(a[i]); sum += a[i]; }
    right[len-N] = sum;
    for (int i = len-N-1; i >= N; i--) {
        if (a[i] < top_max()) { sum += a[i] - top_max(); pop_max(); push_max(a[i]); }
        right[i] = sum;
    }

    long long ans = -1e18;
    for (int i = N; i <= 2*N; i++) {
        if (left[i] - right[i] > ans) ans = left[i] - right[i];
    }
    printf("%lld\n", ans);
    free(a); free(left); free(right);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll *a;
    int sz;
    int cap;
    int is_min; /* 1: min-heap, 0: max-heap */
} Heap;

void heap_init(Heap *h, int cap, int is_min) {
    h->a = (ll *)malloc(sizeof(ll) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
    h->is_min = is_min;
}

int heap_cmp(Heap *h, ll x, ll y) {
    if (h->is_min) return x < y;
    return x > y;
}

void heap_push(Heap *h, ll x) {
    int i = ++h->sz;
    h->a[i] = x;
    while (i > 1) {
        int p = i >> 1;
        if (heap_cmp(h, h->a[p], h->a[i])) break;
        ll tmp = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = tmp;
        i = p;
    }
}

ll heap_top(Heap *h) {
    return h->a[1];
}

ll heap_pop(Heap *h) {
    ll ret = h->a[1];
    ll x = h->a[h->sz--];
    if (h->sz == 0) return ret;
    int i = 1;
    while ((i << 1) <= h->sz) {
        int l = i << 1, r = l + 1, best = l;
        if (r <= h->sz && heap_cmp(h, h->a[r], h->a[l])) best = r;
        if (heap_cmp(h, x, h->a[best])) break;
        h->a[i] = h->a[best];
        i = best;
    }
    h->a[i] = x;
    return ret;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 3 * N;
    ll *a = (ll *)malloc(sizeof(ll) * M);
    for (int i = 0; i < M; i++) scanf("%lld", &a[i]);

    /* left[i]: maximum sum of N elements chosen from a[0..i], for i in [N-1, 2N-1] */
    ll *left = (ll *)malloc(sizeof(ll) * M);
    Heap minh;
    heap_init(&minh, M, 1);

    ll sumL = 0;
    for (int i = 0; i < N; i++) {
        heap_push(&minh, a[i]);
        sumL += a[i];
    }
    left[N - 1] = sumL;

    for (int i = N; i < 2 * N; i++) {
        heap_push(&minh, a[i]);
        sumL += a[i];
        sumL -= heap_pop(&minh); /* keep largest N */
        left[i] = sumL;
    }

    /* right[i]: minimum sum of N elements chosen from a[i..3N-1], for i in [N, 2N] */
    ll *right = (ll *)malloc(sizeof(ll) * (M + 1));
    Heap maxh;
    heap_init(&maxh, M, 0);

    ll sumR = 0;
    for (int i = M - 1; i >= 2 * N; i--) {
        heap_push(&maxh, a[i]);
        sumR += a[i];
    }
    right[2 * N] = sumR;

    for (int i = 2 * N - 1; i >= N; i--) {
        heap_push(&maxh, a[i]);
        sumR += a[i];
        sumR -= heap_pop(&maxh); /* keep smallest N */
        right[i] = sumR;
    }

    ll ans = left[N - 1] - right[N];
    for (int i = N - 1; i < 2 * N; i++) {
        ll cand = left[i] - right[i + 1];
        if (cand > ans) ans = cand;
    }

    printf("%lld\n", ans);

    free(a);
    free(left);
    free(right);
    free(minh.a);
    free(maxh.a);
    return 0;
}

