public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine().trim());
        int[] a = new int[3 * N];
        for (int i = 0; i < 3 * N; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        // left[i] = max sum of N elements from a[0..i-1], for i = N to 2N
        long[] left = new long[3 * N + 1];
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(); // min-heap to keep largest N
        long sumL = 0;
        for (int i = 0; i < N; i++) {
            minHeap.add(a[i]);
            sumL += a[i];
        }
        left[N] = sumL;
        for (int i = N; i < 2 * N; i++) {
            // consider a[i], update for left[i+1]
            if (a[i] > minHeap.peek()) {
                sumL -= minHeap.poll();
                minHeap.add(a[i]);
                sumL += a[i];
            }
            left[i + 1] = sumL;
        }

        // right[i] = min sum of N elements from a[i..3N-1], for i = N to 2N
        long[] right = new long[3 * N + 1];
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder()); // max-heap to keep smallest N
        long sumR = 0;
        for (int i = 3 * N - 1; i >= 2 * N; i--) {
            maxHeap.add(a[i]);
            sumR += a[i];
        }
        right[2 * N] = sumR;
        for (int i = 2 * N - 1; i >= N; i--) {
            // consider a[i], update for right[i]
            if (a[i] < maxHeap.peek()) {
                sumR -= maxHeap.poll();
                maxHeap.add(a[i]);
                sumR += a[i];
            }
            right[i] = sumR;
        }

        long ans = Long.MIN_VALUE;
        for (int i = N; i <= 2 * N; i++) {
            ans = Math.max(ans, left[i] - right[i]);
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long[] a = new long[3 * N];
        for (int i = 0; i < 3 * N; i++) a[i] = fs.nextLong();

        // left[i]: maximum possible sum of N elements chosen from a[0..i]
        // valid for i >= N-1
        long[] left = new long[3 * N];
        PriorityQueue<Long> minHeap = new PriorityQueue<>();
        long sumLeft = 0;
        for (int i = 0; i < 3 * N; i++) {
            minHeap.add(a[i]);
            sumLeft += a[i];
            if (minHeap.size() > N) {
                sumLeft -= minHeap.poll();
            }
            if (minHeap.size() == N) {
                left[i] = sumLeft;
            }
        }

        // right[i]: minimum possible sum of N elements chosen from a[i..3N-1]
        // valid for i <= 2N
        long[] right = new long[3 * N];
        PriorityQueue<Long> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long sumRight = 0;
        for (int i = 3 * N - 1; i >= 0; i--) {
            maxHeap.add(a[i]);
            sumRight += a[i];
            if (maxHeap.size() > N) {
                sumRight -= maxHeap.poll();
            }
            if (maxHeap.size() == N) {
                right[i] = sumRight;
            }
        }

        long ans = Long.MIN_VALUE;
        // Split after i: first N chosen from [0..i], last N chosen from [i+1..3N-1]
        // Need i in [N-1, 2N-1]
        for (int i = N - 1; i <= 2 * N - 1; i++) {
            ans = Math.max(ans, left[i] - right[i + 1]);
        }

        System.out.println(ans);
    }
